            2u -> {   // ShortValue
                r.readBits(1)   // value-start
                _shortValue = ExiPrimitives.readSignedInteger(r).toShort()
                r.readBits(1)   // child EE
            }
            3u -> {   // IntValue
                r.readBits(1)   // value-start
                _intValue = ExiPrimitives.readSignedInteger(r).toInt()
                r.readBits(1)   // child EE
            }
            4u -> {   // PhysicalValue
