    }

    private fun encodeReferenceType(w: BitWriter, msg: ReferenceType) {
        var st96 = 0
        var done96 = false
        while (!done96) {
            when (st96) {
                0 -> {
                    if (msg.id != null) {
                        w.writeBits(0u, 3)   // Id
                        ExiPrimitives.writeStringValue(w, msg.id!!)
                        st96 = 1
                    } else if (msg.type != null) {
                        w.writeBits(1u, 3)   // Type
