                        ExiPrimitives.writeStringValue(w, msg.uRI!!)
                        st96 = 3
                    } else if (msg.transforms != null) {
                        w.writeBits(3u, 3)   // Transforms
                        encodeTransformsType(w, msg.transforms!!)
                        st96 = 4
                    } else {
                        w.writeBits(4u, 3)   // SE(DigestMethod)
                        encodeDigestMethodType(w, msg.digestMethod)
                        done96 = true
                    }
                }
                1 -> {
                    if (msg.type != null) {
                        w.writeBits(0u, 3)   // Type
                        ExiPrimitives.writeStringValue(w, msg.type!!)
                        st96 = 2
                    } else if (msg.uRI != null) {
                        w.writeBits(1u, 3)   // URI
                        ExiPrimitives.writeStringValue(w, msg.uRI!!)
                        st96 = 3
                    } else if (msg.transforms != null) {
                        w.writeBits(2u, 3)   // Transforms
                        encodeTransformsType(w, msg.transforms!!)
                        st96 = 4
                    } else {
                        w.writeBits(3u, 3)   // SE(DigestMethod)
                        encodeDigestMethodType(w, msg.digestMethod)
                        done96 = true
                    }
                }
                2 -> {
                    if (msg.uRI != null) {
                        w.writeBits(0u, 2)   // URI
                        ExiPrimitives.writeStringValue(w, msg.uRI!!)
                        st96 = 3
                    } else if (msg.transforms != null) {
                        w.writeBits(1u, 2)   // Transforms
                        encodeTransformsType(w, msg.transforms!!)
                        st96 = 4
                    } else {
                        w.writeBits(2u, 2)   // SE(DigestMethod)
                        encodeDigestMethodType(w, msg.digestMethod)
                        done96 = true
                    }
                }
                3 -> {
                    if (msg.transforms != null) {
                        w.writeBits(0u, 2)   // Transforms
                        encodeTransformsType(w, msg.transforms!!)
                        st96 = 4
                    } else {
                        w.writeBits(1u, 2)   // SE(DigestMethod)
                        encodeDigestMethodType(w, msg.digestMethod)
                        done96 = true
                    }
                }
                4 -> {
                    w.writeBits(0u, 1)   // SE(DigestMethod)
                    encodeDigestMethodType(w, msg.digestMethod)
                    done96 = true
                }
            }
        }
        w.writeBits(0u, 1)   // SE
        w.writeBits(0u, 1)   // value-start
        ExiPrimitives.writeBinary(w, msg.digestValue)
        w.writeBits(0u, 1)   // child EE
        w.writeBits(0u, 1)   // element EE
    }

    private fun decodeReferenceType(r: BitReader): ReferenceType {
        var _id: String? = null
        var _type: String? = null
        var _uRI: String? = null
        var _transforms: TransformsType? = null
        var _digestMethod: DigestMethodType? = null
        var st97 = 0
        var done97 = false
        while (!done97) {
            when (st97) {
                0 -> {
                    when (r.readBits(3)) {
                        0u -> {
                            _id = ExiPrimitives.readStringValue(r)
                            st97 = 1
                        }
                        1u -> {
                            _type = ExiPrimitives.readStringValue(r)
                            st97 = 2
                        }
                        2u -> {
                            _uRI = ExiPrimitives.readStringValue(r)
                            st97 = 3
                        }
                        3u -> {
                            _transforms = decodeTransformsType(r)
                            st97 = 4
                        }
                        4u -> {   // SE(DigestMethod)
                            _digestMethod = decodeDigestMethodType(r)
                            done97 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                1 -> {
                    when (r.readBits(3)) {
                        0u -> {
                            _type = ExiPrimitives.readStringValue(r)
                            st97 = 2
                        }
                        1u -> {
                            _uRI = ExiPrimitives.readStringValue(r)
                            st97 = 3
                        }
                        2u -> {
                            _transforms = decodeTransformsType(r)
                            st97 = 4
                        }
                        3u -> {   // SE(DigestMethod)
                            _digestMethod = decodeDigestMethodType(r)
                            done97 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                2 -> {
                    when (r.readBits(2)) {
                        0u -> {
                            _uRI = ExiPrimitives.readStringValue(r)
                            st97 = 3
                        }
                        1u -> {
                            _transforms = decodeTransformsType(r)
                            st97 = 4
                        }
                        2u -> {   // SE(DigestMethod)
                            _digestMethod = decodeDigestMethodType(r)
                            done97 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                3 -> {
                    when (r.readBits(2)) {
                        0u -> {
                            _transforms = decodeTransformsType(r)
                            st97 = 4
                        }
                        1u -> {   // SE(DigestMethod)
                            _digestMethod = decodeDigestMethodType(r)
                            done97 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
                4 -> {
                    when (r.readBits(1)) {
                        0u -> {   // SE(DigestMethod)
                            _digestMethod = decodeDigestMethodType(r)
                            done97 = true
                        }
                        else -> throw IllegalArgumentException("invalid optional-run event code")
                    }
                }
            }
        }
        r.readBits(1)   // SE
        r.readBits(1)   // value-start
        val _digestValue = ExiPrimitives.readBinary(r)
        r.readBits(1)   // child EE
        r.readBits(1)   // element EE
        return ReferenceType(_id, _type, _uRI, _transforms, _digestMethod!!, _digestValue)
    }

    private fun encodeTransformsType(w: BitWriter, msg: TransformsType) {
        val list = msg.transform
        require(list.size in 1..2147483647) { "list size out of schema range" }
        for (i in list.indices) {
            w.writeBits(0u, if (i == 0) 1 else 2)   // SE(item)
            encodeTransformType(w, list[i])
        }
        w.writeBits(1u, 2)   // list terminator / element EE
    }

    private fun decodeTransformsType(r: BitReader): TransformsType {
        val list = ArrayList<TransformType>()
        r.readBits(1)   // SE(item) first
        list.add(decodeTransformType(r))
        while (true) {
            val ec = r.readBits(2)
            if (ec == 1u) break   // element EE
            require(ec == 0u && list.size < 2147483647) { "invalid repeating-element event code" }
            list.add(decodeTransformType(r))
        }
        return TransformsType(list)
    }

    private fun encodeTransformType(w: BitWriter, msg: TransformType) {
        w.writeBits(0u, 1)   // AT(required attribute)
        ExiPrimitives.writeStringValue(w, msg.algorithm)
        var st98 = 0
        var done98 = false
        while (!done98) {
            when (st98) {
                0 -> {
                    if (msg.xPath != null) {
                        w.writeBits(0u, 3)   // XPath
                        w.writeBits(0u, 1)   // value-start
                        ExiPrimitives.writeStringValue(w, msg.xPath!!)
                        w.writeBits(0u, 1)   // child EE
                        st98 = 1
                    } else if (msg.aNY != null) {
                        w.writeBits(3u, 3)   // ANY
                        w.writeBits(0u, 1)   // value-start
                        ExiPrimitives.writeBinary(w, msg.aNY!!)
                        w.writeBits(0u, 1)   // child EE
                        st98 = 2
                    } else {
                        w.writeBits(2u, 3)   // element EE
                        done98 = true
                    }
                }
                1 -> {
                    if (msg.aNY != null) {
                        w.writeBits(2u, 2)   // ANY
                        w.writeBits(0u, 1)   // value-start
                        ExiPrimitives.writeBinary(w, msg.aNY!!)
                        w.writeBits(0u, 1)   // child EE
                        st98 = 2
                    } else {
                        w.writeBits(1u, 2)   // element EE
                        done98 = true
                    }
                }
                2 -> {
                    w.writeBits(0u, 1)   // element EE
                    done98 = true
                }
            }
        }
    }

